settings.markdownTextPattern:
// --- ZABEZPIECZENIE PRZED BŁĘDAMI ---
// Ten blok gwarantuje, że kod nie "wywali się", jeśli data jest null
var bezpieczneDane = data || []; 

// Zmienne na wyniki
var displayError = null;
var displaySource = null;

// --- LOGIKA POBIERANIA DANYCH ---
safeLoop: // Etykieta pętli
for (var i = 0; i < bezpieczneDane.length; i++) {
    var series = bezpieczneDane[i];
    
    // Sprawdź czy seria ma dane
    if (!series || !series.data || series.data.length === 0) continue;
    
    // Pobierz ostatni punkt
    var lastVal = series.data[series.data.length - 1][1];
    
    // Rozpoznaj klucz (ignorując wielkość liter)
    var key = (series.dataKey.label || series.dataKey.name || "").toLowerCase();
    
    if (key === 'error_code') {
        displayError = Number(lastVal);
    }
    else if (key === 'time_source') {
        displaySource = Number(lastVal);
    }
}

// --- DIAGNOSTYKA WIZUALNA (Co widzi widget?) ---
// Jeśli nie znaleziono danych, wyświetlamy informację DEBUG
if (displayError === null && displaySource === null) {
    return `
    <div style="background: orange; color: black; padding: 20px; font-weight: bold; text-align: center;">
        <h3>TRYB DIAGNOSTYCZNY</h3>
        <p>Widget działa, ale nie znalazł pasujących kluczy.</p>
        <hr>
        <p style="text-align: left; font-size: 12px;">
        Co widzi widget:<br>
        ${bezpieczneDane.map(d => " - " + d.dataKey.name + " (" + d.dataKey.kind + ")").join("<br>") || "BRAK DANYCH WEJŚCIOWYCH (Pusta tablica)"}
        </p>
    </div>
    `;
}

// --- LOGIKA BIZNESOWA (Twoje statusy) ---
var statusy = [];
var isErr = false;
var err = displayError || 0;

if (err === 0) statusy.push("System OK");
else {
    isErr = true;
    if (err & 1) statusy.push("Brak GPS");
    if (err & 2) statusy.push("Błąd Termometru");
    if (err & 4) statusy.push("Błąd SD");
    if (err & 8) statusy.push("Błąd TB");
    if (statusy.length === 0) statusy.push("Kod: " + err);
}

// --- RENDEROWANIE ---
var bg = isErr ? "#ef5350" : "#66bb6a"; // Czerwony / Zielony
return `
<div style="background: ${bg}; color: white; padding: 15px; border-radius: 5px; height: 100%; display: flex; flex-direction: column; justify-content: center;">
    <h2 style="margin: 0; font-size: 20px;">${statusy.join(", ")}</h2>
    <div style="margin-top: 10px; font-size: 12px; opacity: 0.9;">
        Źródło czasu: <b>${displaySource}</b> (Kod błędu: ${err})
    </div>
</div>
`;

settings.markdownTextFunction:
try {
    // --- 1. POBIERANIE DANYCH ---
    var row = (data && data.length > 0) ? data[0] : {};
    var errorCodeVal = row['error_code']; 
    var timeSourceVal = row['time_source']; 
    var ts = row['error_code|ts'] || row['time_source|ts'] || row['ts'] || 0;

    var errorCode = (typeof errorCodeVal !== 'undefined') ? Number(errorCodeVal) : null;
    var timeSource = (typeof timeSourceVal !== 'undefined') ? Number(timeSourceVal) : null;

    if (errorCode === null && timeSource === null) {
         return '<div style="padding:15px; opacity:0.7;">Oczekiwanie na dane...</div>';
    }

    // --- 2. LOGIKA STATUSÓW ---
    var statusList = [];
    var isError = false;
    var codeInt = errorCode !== null ? errorCode : 0;

    if (codeInt === 0) {
        statusList.push("System OK");
    } else {
        isError = true;
        if ((codeInt & 1) > 0) statusList.push("Brak GPS");
        if ((codeInt & 2) > 0) statusList.push("Awaria Termometru");
        if ((codeInt & 4) > 0) statusList.push("Awaria Karty SD");
        if ((codeInt & 8) > 0) statusList.push("Błąd TB");
        if (statusList.length === 0) statusList.push("Kod błędu: " + codeInt);
    }

    // --- 3. LOGIKA CZASU ---
    var srcStr = "Nieznane";
    if (timeSource === 0) srcStr = "Lokalny";
    if (timeSource === 1) srcStr = "WiFi (NTP)";
    if (timeSource === 2) srcStr = "GPS";
    if (timeSource === null) srcStr = "-";

    var dateString = "--:--";
    if (ts > 0) {
        var d = new Date(ts);
        var pad = function(n) { return n < 10 ? '0' + n : n; };
        dateString = pad(d.getHours()) + ":" + pad(d.getMinutes()) + 
                     " <span style='opacity:0.6; font-size:0.9em'>(" + pad(d.getDate()) + "." + pad(d.getMonth() + 1) + ")</span>";
    }

    // --- 4. WYBÓR KLASY CSS ---
    var cssClass = isError ? "status-error" : "status-ok";
    var iconName = isError ? "warning" : "check_circle";

    // --- 5. RENDEROWANIE ---
    return `
    <div class="system-status-card ${cssClass}">
        <div class="top-label">OSTATNIE DOSTĘPNE DANE</div>
        <div class="card-header">
            <i class="material-icons icon colored-icon">${iconName}</i>
            <div class="main-text">${statusList.join("<br>")}</div>
        </div>
        <div class="card-details">
            <div class="detail-row">
                <span>Źródło czasu:</span>
                <span class="highlight-text">${srcStr}</span>
            </div>
            <div class="detail-row">
                <span>Czas:</span>
                <span>${dateString}</span>
            </div>
        </div>
    </div>
    `;

} catch (e) {
    return '<div style="color:red; padding:10px;">Błąd JS: ' + e.message + '</div>';
}

