.tb-dashboard-page.dark .header-title { color: #ffffff; }
.tb-dashboard-page.dark .label { color: #94a3b8; }
.tb-dashboard-page.dark .value-text { color: #e0e3e7; } /* To koloruje IP i SSID na biało */
.tb-dashboard-page.dark .ip-text { color: #38bdf8; }
.tb-dashboard-page.dark .side-btn.offline { background-color: #0f172a; color: #475569; border: 1px solid #1e293b; }

