settings.markdownTextFunction:
try {
    // --- 1. POBIERANIE DANYCH ---
    var row = (data && data.length > 0) ? data[0] : {};

    function safeGet(key) {
        return (row[key] !== undefined && row[key] !== null) ? row[key] : null;
    }

    var rawSSID = safeGet('ssid');
    var rawIP = safeGet('ip');
    var rawRSSI = safeGet('rssi');
    
    // Atrybuty serwerowe
    var serverActive = safeGet('active');
    var serverLastActivity = safeGet('lastActivityTime');

    // --- 2. LOGIKA ONLINE/OFFLINE ---
    var isAlive = false;

    // A. Atrybut 'active'
    if (serverActive !== null) {
        isAlive = (serverActive === true || serverActive === "true");
    } 
    // B. lastActivityTime
    else if (serverLastActivity !== null) {
        var now = Date.now();
        var diff = now - parseInt(serverLastActivity);
        isAlive = (diff < 60000); 
    }
    // C. Awaryjnie (po telemetrii)
    else {
        var lastTs = row['ts'] || row['rssi|ts'] || 0;
        var diffSec = (Date.now() - lastTs) / 1000;
        isAlive = (lastTs > 0 && diffSec < 90);
    }

    // --- 3. FORMATOWANIE ---
    var ssid = (rawSSID) ? rawSSID : "-";
    var ip = (rawIP) ? rawIP : "-";
    
    var rssiVal = (rawRSSI) ? parseInt(rawRSSI) : 0;
    var rssiText = (rssiVal !== 0) ? rssiVal : "-";

    var isOnline = (isAlive && ip !== "-" && ip !== "0.0.0.0");
    var statusColor = isOnline ? "#4CAF50" : "#F44336";
    var statusText = isOnline ? "Połączono" : "Brak połączenia";

    // --- 4. LOGIKA KLAS KOLORÓW (NOWOŚĆ) ---
    // Zamiast wpisywać kolor #HEX, przypisujemy nazwę klasy
    var rssiClass = "col-grey"; // Domyślnie szary

    if (isOnline && rssiVal !== 0) {
        if (rssiVal >= -60) rssiClass = "col-green";       // Zielony
        else if (rssiVal >= -75) rssiClass = "col-orange"; // Pomarańczowy
        else rssiClass = "col-red";                        // Czerwony
    }

    // --- 5. HTML ---
    var html = '<div class="network-card">';
    html += '<div class="card-flex-container">';

    // LEWA KOLUMNA
    html += '<div class="left-col">';
        html += '<div class="card-header">';
        html += '<div class="status-indicator" style="background-color: ' + statusColor + '; box-shadow: 0 0 8px ' + statusColor + ';"></div>';
        html += '<span class="header-title">' + statusText + '</span>';
        html += '</div>';

        html += '<div class="info-row"><span class="label">Sieć WiFi:</span><span class="value-text">' + ssid + '</span></div>';
        html += '<div class="info-row"><span class="label">Adres IP:</span><span class="value-text ip-text">' + ip + '</span></div>';
        
        html += '<div class="info-row">';
        html += '<span class="label">Sygnał (RSSI):</span>';
        // Tutaj wstawiamy klasę rssiClass
        html += '<span class="value-text ' + rssiClass + '" style="font-weight:bold;">' + rssiText + ' dBm</span>';
        html += '</div>';

        if (!isOnline && serverLastActivity) {
             var lastDate = new Date(parseInt(serverLastActivity));
             var hh = ("0" + lastDate.getHours()).slice(-2);
             var mm = ("0" + lastDate.getMinutes()).slice(-2);
             html += '<div class="info-row" style="margin-top:5px;"><span class="label" style="font-size:0.8em; color:#F44336;">Ostatnio widziano: ' + hh + ':' + mm + '</span></div>';
        }

    html += '</div>';

    // PRAWA KOLUMNA
    html += '<div class="right-col">';
        if (isOnline) {
            html += '<a href="http://' + ip + '" target="_blank" class="side-btn online">';
            html += '<mat-icon class="material-icons" style="font-size: 28px; width: 28px; height: 28px; margin-bottom: 4px; display: block;">language</mat-icon>';
            html += '<span>OTWÓRZ<br>SERVER</span>';
            html += '</a>';
        } else {
            html += '<div class="side-btn offline">';
            html += '<mat-icon class="material-icons" style="font-size: 28px; width: 28px; height: 28px; margin-bottom: 4px; display: block;">wifi_off</mat-icon>';
            html += '<span>OFFLINE</span>';
            html += '</div>';
        }
    html += '</div>'; 
    html += '</div>';
    html += '</div>';

    return html;

} catch (e) {
    return '<div style="color:red; padding:10px; font-size:12px;">Błąd JS: ' + e.message + '</div>';
}

