/* --- 1. USTAWIENIA OGÓLNE I TŁO STRONY --- */
.tb-dashboard-page.dark {
    background-color: #0f172a !important; /* Main Background */
}

/* --- 2. KONFIGURACJA WIDGETÓW (KONTENERY) --- */
.tb-widget-container > .tb-widget {
    border-radius: 8px;
}

/* Zapobieganie zmianie kursora na zwykłych widgetach */
gridster-item:not(.tb-noselect) > .tb-widget-container > .tb-widget {
    cursor: default !important;
}

/* Tło i główny kolor tekstu dla wszystkich widgetów w trybie Dark */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget,
.tb-dashboard-page.dark .tb-widget-container .mat-card, 
.tb-dashboard-page.dark .tb-widget-container .tb-comp-card,
.tb-dashboard-page.dark .tb-widget-content {
    background: #1e293b !important; /* Widget Background */
    background-color: #1e293b !important;
    color: #e0e3e7 !important;      /* Main Text Color */
    box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.5) !important;
    border: 1px solid #334155 !important; /* Subtle Border */
}

/* --- 3. AGRESYWNA ZMIANA WSZYSTKICH TEKSTÓW ("MŁOT") --- */
.tb-dashboard-page.dark .tb-widget-container {
    color: #e0e3e7 !important;
}

/* Gwiazdka * wymusza kolor na każdym elemencie wewnątrz */
.tb-dashboard-page.dark .tb-widget-container * {
    color: #e0e3e7 !important;
}

/* --- 4. WYKRESY (FLOT CHARTS & APEX) --- */
/* Główne teksty wykresów */
.tb-dashboard-page.dark .flot-text,
.tb-dashboard-page.dark .flot-text > div > div {
    color: #94a3b8 !important; /* Secondary Text Color */
}

/* Osie i etykiety (Axis) */
.tb-dashboard-page.dark .flot-y-axis > div, 
.tb-dashboard-page.dark .flot-x-axis > div,
.tb-dashboard-page.dark .flot-tick-label {
    color: #94a3b8 !important;
    fill: #94a3b8 !important; /* Dla SVG */
}

/* Legendy wykresów */
.tb-dashboard-page.dark .legend-label,
.tb-dashboard-page.dark .legendLabel,
.tb-dashboard-page.dark .tb-latest-chart-legend-item-value,
.tb-dashboard-page.dark .tb-time-series-chart-legend-value {
    color: #e0e3e7 !important;
}

/* Etykiety pomocnicze w legendach */
.tb-dashboard-page.dark .tb-latest-chart-legend-item-label div,
.tb-dashboard-page.dark .tb-time-series-chart-legend-type-label,
.tb-dashboard-page.dark .tb-time-series-chart-legend-item-label div {
    color: #94a3b8 !important;
}

/* SVG Text fills */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget svg tspan,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-latest-chart-shape svg text {
    fill: #e0e3e7 !important;
}

/* --- 5. TABELE (TABLE WIDGETS & MATERIAL DESIGN) --- */
/* Nagłówki tabeli */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-header-row,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-header-cell.mat-mdc-table-sticky,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-row .mat-mdc-cell.mat-mdc-table-sticky {
    background-color: #1e293b !important; /* Match widget bg */
}

/* Komórki i linie tabeli */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-header-cell,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-cell {
    color: #e0e3e7 !important;
    border-bottom-color: #334155 !important; /* Dark slate border */
}

/* Strzałki sortowania w tabeli */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-header-cell .mat-sort-header-arrow {
    color: #94a3b8 !important;
}

/* Inputy / Placeholdery w tabelach */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-input-element::placeholder,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-input-element::-webkit-input-placeholder {
    color: #64748b !important; /* Darker slate for placeholders */
}

/* Paginacja (stronicowanie) tabeli */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-paginator,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-paginator button.mat-mdc-icon-button,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-paginator .mat-mdc-select-value,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .mat-mdc-select-arrow {
    color: #94a3b8 !important;
}

/* Przyciski disabled (nieaktywne) */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-paginator button.mat-mdc-icon-button[disabled][disabled],
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-cell button.mat-mdc-icon-button[disabled][disabled] mat-icon {
    color: #334155 !important;
}

/* Checkboxy */
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-cell .mdc-checkbox__background,
.tb-dashboard-page.dark .tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-table .mat-mdc-header-cell .mdc-checkbox__background {
    border-color: #94a3b8 !important;
}

/* --- 6. SIMPLE CARDS (Karty z góry dashboardu) --- */
.tb-dashboard-page.dark .mat-mdc-card-title,
.tb-dashboard-page.dark .mat-card-title,
.tb-dashboard-page.dark .tb-widget-title,
.tb-dashboard-page.dark .widget-title {
    color: #ffffff !important; /* Tytuły niech pozostaną czysto białe dla kontrastu */
}

.tb-dashboard-page.dark .mat-mdc-card-subtitle, 
.tb-dashboard-page.dark .mat-card-subtitle,
.tb-dashboard-page.dark .tb-markdown-view div.param-title,
.tb-dashboard-page.dark .tb-markdown-view .header .subtitle {
    color: #94a3b8 !important;
}

.tb-dashboard-page.dark .mat-mdc-card-content,
.tb-dashboard-page.dark .mat-card-content,
.tb-dashboard-page.dark .value {
    color: #e0e3e7 !important;
}

/* --- 7. MAPA (OpenStreetMap - Dark Mode) --- */
.tb-dashboard-page.dark .leaflet-layer,
.tb-dashboard-page.dark .leaflet-tile-pane {
    /* Dopasowany hue-rotate (190deg) do niebieskawego tła Slate */
    filter: invert(100%) hue-rotate(190deg) brightness(90%) contrast(85%) !important;
}
.tb-dashboard-page.dark .leaflet-marker-pane, 
.tb-dashboard-page.dark .leaflet-popup-pane,
.tb-dashboard-page.dark .leaflet-marker-icon,
.tb-dashboard-page.dark .leaflet-popup,
.tb-dashboard-page.dark .leaflet-tooltip {
    filter: none !important;
}

/* --- 8. WYJĄTKI (Ikony statusów) --- */
.tb-dashboard-page.dark .tb-widget-container mat-icon.mat-warn {
    color: #f44336 !important; /* Czerwony błąd */
}
.tb-dashboard-page.dark .tb-widget-container mat-icon.mat-primary {
    color: #60a5fa !important; /* Rozjaśniony niebieski dla lepszej czytelności na ciemnym */
}

/* --- 9. ELEMENTY INTERAKTYWNE --- */
.tb-widget-container > .tb-widget .tb-table-widget .mat-mdc-row {
    cursor: pointer;
}
.tb-widget-container > .tb-widget .tb-legend-keys {
    cursor: pointer;
}

.tb-dashboard-page.dark .tb-powered-by-footer {
    color: #475569 !important;
}

/* --- STYLE DLA WIDGETU HTML CARD (Status Systemu) --- */

/* 1. BAZA KARTY */
.system-status-card {
    display: flex;
    flex-direction: column;
    justify-content: center;
    height: 100%;
    width: 100%;
    padding: 16px;
    box-sizing: border-box;
    border-radius: 8px;
    transition: all 0.3s ease;
    /* Domyślnie brak tła i kolor tekstu dziedziczony z motywu */
    background: transparent !important;
    color: inherit; 
}

.card-header {
    display: flex;
    align-items: center;
    margin-bottom: 8px;
}

.icon {
    font-size: 32px;
    margin-right: 12px;
    /* Domyślnie brak koloru, dziedziczy tekst */
}

.main-text {
    font-size: 18px;
    font-weight: bold;
    line-height: 1.2;
}

.card-details {
    display: flex;
    flex-direction: column;
    font-size: 11px;
    margin-top: 4px;
    padding-top: 8px;
    /* Linia podziału zawsze delikatna, zgodna z tekstem */
    border-top: 1px solid currentColor;
    opacity: 0.8; 
}

.detail-row {
    display: flex;
    justify-content: space-between;
    margin-bottom: 2px;
}

.highlight-text {
    font-weight: bold;
}
/* ==========================================================================
   KOLOROWANIE TYLKO IKON (IKONY W TRYBIE JASNYM)
   ========================================================================== */
   
/* Status OK - Tylko ikona zielona */
.status-ok .colored-icon {
    color: #388e3c !important; 
}

/* Status ERROR - Tylko ikona czerwona */
.status-error .colored-icon {
    color: #d32f2f !important;
}
/* Opcjonalnie: Czerwona poświata (Cień) w błędzie, ale bez zmiany koloru tekstu */
.status-error {
    box-shadow: inset 0 0 10px rgba(244, 67, 54, 0.1); 
    border: 1px solid rgba(244, 67, 54, 0.3);
}


/* ==========================================================================
   KOLOROWANIE TYLKO IKON (IKONY W TRYBIE CIEMNYM)
   ========================================================================== */

/* Status OK - Dark Mode */
.tb-dashboard-page.dark .status-ok .colored-icon {
    color: #4caf50 !important; /* Jaśniejsza zieleń */
}

/* Status ERROR - Dark Mode */
.tb-dashboard-page.dark .status-error .colored-icon {
    color: #f87171 !important; /* Jaśniejsza czerwień */
}

/* Stylizacja kontenera błędu w trybie ciemnym (tylko ramka/tło, tekst bez zmian) */
.tb-dashboard-page.dark .status-error {
    background-color: rgba(127, 29, 29, 0.2) !important; /* Bardzo delikatne tło */
    border: 1px solid rgba(239, 68, 68, 0.5) !important;
    box-shadow: 0 0 15px rgba(239, 68, 68, 0.1);
}

/* Resetowanie kolorów tekstu w trybie ciemnym, żeby na pewno był biały/szary */
.tb-dashboard-page.dark .system-status-card {
    color: #e0e3e7 !important;
}
.tb-dashboard-page.dark .card-details {
    opacity: 0.7; /* Lekkie przyciemnienie szczegółów */
}
